-- Guest Hub S1c (25 Nov 2026, Ahmed — DECISIONS.md 2026-11-25 «Guest Hub S1c»): a test account's conversation alerts only
-- the system admin; a social chat booking request alerts the conversation's branch; the staff alert names the channel;
-- two lab items. Generated by scripts/hub-s1c-migration.mjs — never edited once applied (CLAUDE.md §12).
-- No unit mode, licence or switch changes. No phone number in this file. Every UPDATE / DELETE carries a WHERE.

-- an account marked «حساب تجربة» (Instagram / Messenger) is the conversation's guest
create or replace function internal.hub_tester_conversation(p_conversation uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select i.tester from public.hub_conversations c join public.hub_channels ch on ch.id = c.channel_id
                     join public.hub_social_identities i on i.channel_id = c.channel_id and i.guest_profile_id = c.guest_profile_id and i.is_test = c.is_test
                    where c.id = p_conversation and ch.provider = 'meta' limit 1), false)
$$;
-- the system admin's own number of «التقارير» (the staff alert of a test account's conversation goes there only)
create or replace function internal.hub_system_admin_recipient() returns uuid
language sql stable security definer set search_path = '' as $$
  select r.id from public.hub_report_recipients r join public.staff s on s.user_id = r.staff_user_id
   where s.role = 'admin' and s.active and r.active order by r.position limit 1
$$;
revoke execute on function internal.hub_tester_conversation(uuid), internal.hub_system_admin_recipient() from public, anon, authenticated;

create or replace function internal.hub_handoff_queue(p_handoff uuid, p_kind text, p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  h public.hub_handoffs;
  v_channel uuid;
  v_n integer := 0;
begin
  select * into h from public.hub_handoffs where id = p_handoff for update;
  if h.id is null or h.closed_at is not null then return 0; end if;
  v_channel := internal.hub_branch_channel(h.branch_slug);
  -- S1c (Ahmed, 25 Nov 2026): a test account's conversation alerts only the system admin — never a reception slot
  if internal.hub_tester_conversation(h.conversation_id) then
    if p_kind = 'alert' and v_channel is not null and internal.hub_system_admin_recipient() is not null
       and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.recipient_id = internal.hub_system_admin_recipient()) then
      insert into public.hub_staff_sends (kind, handoff_id, recipient_id, channel_id, template, is_test)
      values ('alert', h.id, internal.hub_system_admin_recipient(), v_channel, 'hub_staff_alert', h.is_test);
      v_n := 1;
    end if;
    if p_kind = 'alert' then
      update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
    else
      update public.hub_handoffs set escalated_at = p_now where id = h.id;
    end if;
    return v_n;
  end if;
  if p_kind = 'alert' then
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and internal.hub_slot_covers(s, p_now)
      on conflict do nothing;
      get diagnostics v_n = row_count;
      if v_n = 0 then
        insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
        select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
         where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
        on conflict do nothing;
        get diagnostics v_n = row_count;
      end if;
    end if;
    update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
  else
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'escalation', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
         and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.slot_id = s.id)
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
    update public.hub_handoffs set escalated_at = p_now where id = h.id;
  end if;
  return v_n;
end;
$$;

create or replace function internal.hub_extra_alert(p_conversation uuid, p_reason text, p_summary text, p_ref text, p_managers boolean, p_reservation uuid)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  v_id uuid := gen_random_uuid();
  v_branch text;
  v_channel uuid;
  v_n integer := 0;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null then return null; end if;
  -- S1c: «السوشيال» has no branch — the conversation's, else Airport Road (as its hand-offs)
  select coalesce(u.branch_slug, c.branch_slug, 'airport-road') into v_branch from public.hub_units u where u.id = c.unit_id;
  insert into public.hub_handoffs (id, conversation_id, unit_id, branch_slug, reason, summary, ref_text, is_test, extra, reservation_id, status)
  values (v_id, c.id, c.unit_id, v_branch, p_reason, left(p_summary, 120), left(p_ref, 40), c.is_test, true, p_reservation, 'pending');
  v_channel := internal.hub_branch_channel(v_branch);
  -- S1c (Ahmed, 25 Nov 2026): a test account's conversation alerts only the system admin
  if v_channel is not null and internal.hub_tester_conversation(c.id) then
    if internal.hub_system_admin_recipient() is not null then
      insert into public.hub_staff_sends (kind, handoff_id, recipient_id, channel_id, template, is_test)
      values ('alert', v_id, internal.hub_system_admin_recipient(), v_channel, 'hub_staff_alert', c.is_test);
      v_n := 1;
    end if;
  elsif v_channel is not null then
    if not coalesce(p_managers, false) then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', v_id, s.id, v_channel, 'hub_staff_alert', c.is_test from public.hub_staff_slots s
       where s.branch_slug = v_branch and s.active and internal.hub_slot_covers(s, now())
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
    if v_n = 0 then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', v_id, s.id, v_channel, 'hub_staff_alert', c.is_test from public.hub_staff_slots s
       where s.branch_slug = v_branch and s.active and s.role = 'manager'
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
  end if;
  update public.hub_handoffs set alerted_at = now(), status = case when v_n > 0 then 'alerted' else 'email_only' end where id = v_id;
  return v_id;
end;
$$;

create or replace function public.hub_escalations_claim(p_now timestamptz default now(), p_limit integer default 20) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_esc integer := internal.hub_setting_int('hub_escalate_min', 30);
  r record;
  v_to text[];
  v_out jsonb := '[]'::jsonb;
begin
  for r in select c.id, c.state, c.waiting_since, u.branch_slug, c.branch_slug as conv_branch, coalesce(v.name_ar, u.name_ar) as unit_name
             from public.hub_conversations c join public.hub_units u on u.id = c.unit_id left join public.dining_venues v on v.id = u.dining_venue_id
            where c.state = 'human' and c.waiting_since is not null and c.escalated_at is null and not c.is_test
              and c.waiting_since <= p_now - make_interval(mins => v_esc)
            order by c.waiting_since limit least(greatest(coalesce(p_limit, 20), 1), 100)
            for update of c skip locked loop
    update public.hub_conversations set escalated_at = p_now where id = r.id;
    select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x
     where x.scope = 'branch' and x.branch_slug = coalesce(r.branch_slug, r.conv_branch) and x.active;
    -- S1c (Ahmed, 25 Nov 2026): a test account's conversation emails only the active admins
    if internal.hub_tester_conversation(r.id) then
      v_to := array(select u.email from public.staff s join auth.users u on u.id = s.user_id where s.active and s.role = 'admin' and u.email is not null order by u.email);
    elsif cardinality(v_to) = 0 then
      select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x where x.scope = 'central' and x.active;
    end if;
    v_out := v_out || jsonb_build_object('id', r.id, 'short', upper(left(replace(r.id::text, '-', ''), 8)), 'unit_name', r.unit_name, 'state', r.state,
                                         'waiting_min', floor(extract(epoch from p_now - r.waiting_since) / 60)::integer, 'recipients', to_jsonb(v_to));
  end loop;
  return v_out;
end;
$$;

create or replace function public.hub_staff_sends_claim(p_limit integer default 20, p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  s record;
  v_out jsonb := '[]'::jsonb;
begin
  for s in select x.*, ch.address as from_address, ch.waba_id, ch.sending_enabled, coalesce(sl.phone, rr.phone) as to_phone,
                  coalesce(sl.active, rr.active, false) as target_active, h.token, h.branch_slug, h.summary, h.ref_text, h.reason, h.conversation_id,
                  h.closed_at, h.first_reply_at
             from public.hub_staff_sends x
             left join public.hub_channels ch on ch.id = x.channel_id
             left join public.hub_staff_slots sl on sl.id = x.slot_id
             left join public.hub_report_recipients rr on rr.id = x.recipient_id
             left join public.hub_handoffs h on h.id = x.handoff_id
            where x.status = 'queued' and x.is_test = coalesce(p_test, false) order by x.created_at limit least(greatest(coalesce(p_limit, 20), 1), 100) for update of x skip locked loop
    -- an alert or escalation whose hand-off was answered or closed meanwhile is not sent
    if s.to_phone is null or not s.target_active or s.from_address is null
       or (s.kind in ('alert', 'escalation') and (s.closed_at is not null or s.first_reply_at is not null)) then
      update public.hub_staff_sends set status = 'skipped', error_code = case when s.from_address is null then 'no_channel' when s.to_phone is null or not s.target_active then 'no_recipient' else 'answered' end, updated_at = now()
       where id = s.id;
      continue;
    end if;
    update public.hub_staff_sends set status = 'pending', updated_at = now() where id = s.id;
    v_out := v_out || jsonb_build_object(
      'id', s.id, 'kind', s.kind, 'template', s.template, 'language', 'ar', 'is_test', s.is_test,
      'channel_id', s.channel_id, 'from', s.from_address, 'waba_id', s.waba_id, 'sending_enabled', s.sending_enabled, 'to', s.to_phone,
      'handoff', case when s.handoff_id is not null then (
        select jsonb_build_object('token', s.token, 'branch', s.branch_slug, 'summary', s.summary, 'ref', s.ref_text, 'reason', s.reason,
                 'guest_name', coalesce((select nullif(btrim(r.guest_name), '') from public.reservations r where r.phone = g.phone and not r.is_test order by r.created_at desc limit 1),
                                        nullif(btrim(g.wa_profile_name), '')),
                 'guest_phone', g.phone,
                 -- S1c: a social guest has no phone — the alert names the channel instead
                 'channel_kind', (select ch.kind from public.hub_channels ch where ch.id = c.channel_id))
          from public.hub_conversations c join public.guest_profiles g on g.id = c.guest_profile_id where c.id = s.conversation_id) end,
      'report', case when s.kind = 'report' then (select jsonb_build_object('day', d.day, 'data', d.data) from public.hub_daily_reports d where d.day = s.report_day)
                     when s.kind = 'report_test' then jsonb_build_object('day', s.report_day, 'data', s.payload) end);
  end loop;
  return v_out;
end;
$$;

-- two more lab items of «السوشيال»: a greeting alone (the Messenger failure of 25 Nov 2026 21:41) and an English greeting
do $$
declare v_sort integer := coalesce((select max(sort) from public.hub_test_items), 0) + 1;
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($s1c$[{"key":"s1-11","unit":"social","language":"ar","messages":["السلام عليكم"],"expect":{"action":"conversation","steps":[{"outcome":"reply","must_include":["وعليكم السلام"],"must_not_include":["سيكمل معك"]}]},"note":"a greeting alone on Messenger from an account with no name (25 Nov 2026 21:41: the code crashed on the quick replies of the brand unit and the guest got the hand-off notice)","tags":["conversation","social","greeting"],"context":{}},{"key":"s1-12","unit":"social","language":"en","messages":["Hi"],"expect":{"action":"conversation","steps":[{"outcome":"reply","must_not_include":["will continue with you"]}]},"note":"an English greeting alone on «السوشيال»: a reply with the quick replies, never the hand-off notice","tags":["conversation","social","greeting"],"context":{}}]$s1c$::jsonb) with ordinality as x(e, o)
  on conflict (key) do nothing;
end $$;
